"""Historical baseline comparison; only executed as a command."""
SOURCE = '"""Compare freshly regenerated outputs with final manuscript Tables 4 and 5."""\nimport csv, json, hashlib, sys\nfrom pathlib import Path\nfrom datetime import datetime, timezone\nROOT = Path(__file__).resolve().parents[2]\nBASE = ROOT\ndef rows(p):\n    with p.open(newline=\'\',encoding=\'utf-8-sig\') as f: return list(csv.DictReader(f))\ndoc = json.loads((ROOT/\'output/metadata/manuscript_baseline_tables.json\').read_text(encoding=\'utf-8\'))\nperf = {r[\'model\']: r for r in rows(BASE/\'outputs_v2/tables/model_performance.csv\')}\nthresholds = {float(r[\'threshold\']): r for r in rows(BASE/\'outputs_v2/tables/logistic_regression_threshold_sensitivity.csv\')}\nnames={\'RF\':\'Random Forest\',\'LR\':\'Logistic Regression\',\'GB\':\'Gradient Boosting\',\'SVM\':\'SVM\'}\nchecks=[]\nfor r in doc[\'tables\'][3][\'rows\'][1:]:\n    model=names[r[0]]; new=perf[model]\n    for idx,key in enumerate([\'accuracy\',\'precision\',\'recall\',\'f1\',\'roc_auc\',\'pr_auc\'],1):\n        checks.append({\'table\':4,\'model\':model,\'field\':key,\'old\':r[idx],\'new\':float(new[key]),\'pass\':abs(float(r[idx])-float(new[key])) <= .000500001})\n    for key,old in zip([\'tp\',\'fp\',\'fn\'],r[7].split(\'/\')):\n        checks.append({\'table\':4,\'model\':model,\'field\':key,\'old\':old,\'new\':int(new[key]),\'pass\':int(old)==int(new[key])})\n    checks.append({\'table\':4,\'model\':model,\'field\':\'warning_workload\',\'old\':r[8],\'new\':int(new[\'warning_workload\']),\'pass\':int(r[8])==int(new[\'warning_workload\'])})\nfor r in doc[\'tables\'][4][\'rows\'][1:]:\n    new=thresholds[float(r[0])]\n    for idx,key in enumerate([\'precision\',\'recall\',\'f1\',\'warning_workload\',\'false_alarms\',\'missed_hazardous_cases\'],1):\n        val=float(new[key]); old=float(r[idx]); tol=.000500001 if idx<=3 else 0\n        checks.append({\'table\':5,\'model\':\'Logistic Regression\',\'cutoff\':float(r[0]),\'field\':key,\'old\':r[idx],\'new\':val,\'pass\':abs(val-old)<=tol})\npassed=all(c[\'pass\'] for c in checks)\n(ROOT/\'output/metadata/baseline_comparison.json\').write_text(json.dumps({\'passed\':passed,\'checks\':checks},indent=2),encoding=\'utf-8\')\nmeta=json.loads((BASE/\'outputs_v2/metadata/run_metadata.json\').read_text())\ndata=json.loads((BASE/\'outputs/metadata/dataset_validation.json\').read_text())\nlines=[\'# Original reproduction report\',\'\',f\'UTC verification time: {datetime.now(timezone.utc).isoformat()}\',f\'Gate: {"PASS" if passed else "STOP — baseline mismatch"}\', \'\',f"Dataset: {data[\'rows\']} records, {data[\'positive\']} positive, {data[\'negative\']} negative, positive ratio {data[\'positive\']/data[\'rows\']:.12f}; {data[\'features\']} input features.", \'\', \'The unmodified supplied code was executed with `python -m src.run_all` in a separate environment. The initial launch occurred while installation was still completing and failed on an unavailable pandas import; the retained successful rerun log is authoritative. Original source files outside revision_analysis were not changed.\', \'\', \'Comparison uses exact agreement for counts and 0.000500001 tolerance for manuscript values printed to three decimal places.\', \'\', \'| Table | Model | Metric | Manuscript | Recomputed | Match |\',\'|---|---|---|---|---|---|\']\nfor c in checks:\n    lines.append(f"| {c[\'table\']} | {c[\'model\']}"+(f" at {c[\'cutoff\']}" if \'cutoff\' in c else \'\')+f" | {c[\'field\']} | {c[\'old\']} | {c[\'new\']:.12g} | {c[\'pass\']} |")\nlines += [\'\', \'## Configuration\', \'\', \'```json\', json.dumps(meta,indent=2),\'```\',\'\', \'Full model settings: src/original_baseline/config/frozen_model_parameters_v2.yaml. Actual parameter export: src/original_baseline/outputs_v2/metadata/model_parameters.json. Split: 70:30 stratified, seed 42. Preprocessing: four categorical variables one-hot encoded; 14 numeric variables standardized for LR/SVM and passed through for RF/GB; no imputation or resampling; preprocessing fitted on training data inside Pipeline.\']\n(ROOT/\'output/metadata/original_reproduction_report.md\').write_text(\'\\n\'.join(lines),encoding=\'utf-8\')\nprint(json.dumps({\'passed\':passed,\'checks\':len(checks),\'mismatches\':[c for c in checks if not c[\'pass\']]},indent=2))\nsys.exit(0 if passed else 2)\n'
if __name__ == "__main__":
    exec(compile(SOURCE, __file__, "exec"), globals())
